CREATE TABLE roles (id BIGINT AUTO_INCREMENT PRIMARY KEY, name VARCHAR(30) NOT NULL UNIQUE);
CREATE TABLE users (id BIGINT AUTO_INCREMENT PRIMARY KEY, name VARCHAR(120) NOT NULL, email VARCHAR(180) NOT NULL UNIQUE, phone VARCHAR(30), password_hash VARCHAR(255) NOT NULL, role_id BIGINT NOT NULL, is_verified BOOLEAN NOT NULL DEFAULT FALSE, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, CONSTRAINT fk_users_role FOREIGN KEY (role_id) REFERENCES roles(id));
CREATE TABLE pets (id BIGINT AUTO_INCREMENT PRIMARY KEY, owner_id BIGINT NOT NULL, name VARCHAR(100) NOT NULL, species VARCHAR(40) NOT NULL, breed VARCHAR(80), age_years DECIMAL(4,1), notes TEXT, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT fk_pets_owner FOREIGN KEY (owner_id) REFERENCES users(id));
CREATE TABLE caretaker_profiles (id BIGINT AUTO_INCREMENT PRIMARY KEY, user_id BIGINT NOT NULL UNIQUE, bio TEXT, experience_years DECIMAL(4,1), hourly_rate DECIMAL(10,2) NOT NULL, service_areas VARCHAR(500), is_verified BOOLEAN NOT NULL DEFAULT FALSE, CONSTRAINT fk_profiles_user FOREIGN KEY (user_id) REFERENCES users(id));
CREATE TABLE services (id BIGINT AUTO_INCREMENT PRIMARY KEY, name VARCHAR(100) NOT NULL, description TEXT, default_hourly_rate DECIMAL(10,2), is_active BOOLEAN NOT NULL DEFAULT TRUE);
CREATE TABLE bookings (id BIGINT AUTO_INCREMENT PRIMARY KEY, customer_id BIGINT NOT NULL, caretaker_id BIGINT NOT NULL, pet_id BIGINT NOT NULL, service_id BIGINT NOT NULL, starts_at DATETIME NOT NULL, ends_at DATETIME NOT NULL, status VARCHAR(30) NOT NULL DEFAULT 'REQUESTED', hourly_rate DECIMAL(10,2) NOT NULL, notes TEXT, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT fk_booking_customer FOREIGN KEY (customer_id) REFERENCES users(id), CONSTRAINT fk_booking_caretaker FOREIGN KEY (caretaker_id) REFERENCES users(id), CONSTRAINT fk_booking_pet FOREIGN KEY (pet_id) REFERENCES pets(id), CONSTRAINT fk_booking_service FOREIGN KEY (service_id) REFERENCES services(id));
CREATE TABLE payments (id BIGINT AUTO_INCREMENT PRIMARY KEY, booking_id BIGINT NOT NULL UNIQUE, amount DECIMAL(10,2) NOT NULL, currency CHAR(3) NOT NULL DEFAULT 'INR', status VARCHAR(30) NOT NULL DEFAULT 'PENDING', provider_reference VARCHAR(160), created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT fk_payment_booking FOREIGN KEY (booking_id) REFERENCES bookings(id));
CREATE TABLE reviews (id BIGINT AUTO_INCREMENT PRIMARY KEY, booking_id BIGINT NOT NULL UNIQUE, author_id BIGINT NOT NULL, caretaker_id BIGINT NOT NULL, rating TINYINT NOT NULL, comment TEXT, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT fk_review_booking FOREIGN KEY (booking_id) REFERENCES bookings(id), CONSTRAINT fk_review_author FOREIGN KEY (author_id) REFERENCES users(id), CONSTRAINT fk_review_caretaker FOREIGN KEY (caretaker_id) REFERENCES users(id));
CREATE TABLE admin_actions (id BIGINT AUTO_INCREMENT PRIMARY KEY, admin_id BIGINT NOT NULL, action VARCHAR(120) NOT NULL, target_type VARCHAR(60), target_id BIGINT, details TEXT, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT fk_admin_action_user FOREIGN KEY (admin_id) REFERENCES users(id));
